DELETE FROM transactions
WHERE user_id = #{userId}
  AND tran_date BETWEEN #{startDate, jdbcType=TIMESTAMP}
    AND #{endDate, jdbcType=TIMESTAMP}

DELETE FROM snapshots
WHERE user_id = #{userId}
  AND snapshot_date BETWEEN #{startDate, jdbcType=TIMESTAMP}
    AND #{endDate, jdbcType=TIMESTAMP}
